def get_bucket(n, primes, is_prime):
	bucket = 1
	for prime in primes:
		if n == 1:
			return bucket
		if is_prime[n]:
			bucket *= n
			break
		count = 0
		while n % prime == 0:
			n //= prime
			count += 1
		if count % 2 == 1:
			bucket *= prime
	return bucket
