		return set((u for (u, node) in self.V.items() if len(node) == 1))

	def node(self, u):
		return self.V[u]

	def weight(self, u, v):
		(u, v) = (u, v) if u < v else (v, u)
		return self.w[u, v]

	def __len__(self):
		return len(self.V)

	def calc_freqs(self):
		updateables = self.leaves()
		while updateables:
			v = updateables.pop()
			updateables.update(update_freq(v, self))

def freq_sum(node, v, w=0):
	freq = dict()
	freq[2] = (w, 1)
	for (u, e) in node.out_edges.items():
		if u == v:
			continue
		for (k, (f, n)) in e.items():
			(f0, n0) = freq.get(k + 1, (0, 0))
			freq[k + 1] = ((f0 + f + n * w) % p, n0 + n)
	return freq

def update_freq(u, G):
	node = G.node(u)
	assert len(node.nf) <= 1
	nodes = node.nf if len(node.nf) == 1 else node.out_edges.keys()
	updateable = set()
	for v in nodes:
		other = G.node(v)
		if not other.nf:
			continue
		if u in other.nf:
			other.nf.discard(u)
			other.out_edges[u] = freq_sum(node, v, G.weight(u, v))
		if len(other.nf) <= 1:
			updateable.add(v)
	return updateable

class FacModp:

	def __init__(self):
		self.x = 1

	def __call__(self, i):
		x = self.x
		self.x = self.x * i % p
		return x

def factorial_per_k(n):
	f = FacModp()
	x = [f(i) for i in range(1, n + 1)]
	f = FacModp()
	y = [f(i) for i in range(n, 0, -1)]
	return [xi * yi % p for (xi, yi) in zip(x, reversed(y))]

