import math

def power(a, n, mod):
	res = 1
	while n > 0:
		if n & 1 == 1:
			res = res % mod * a % mod % mod
			n -= 1
		a = a % mod * a % mod % mod
		n = n // 2
	return res

def gcd(a, b, n, mod):
	if a == b:
		return (power(a, n, mod) + power(b, n, mod)) % mod
	possible = 1
	total = a - b
	for i in range(1, int(math.sqrt(total)) + 1):
		if total % i == 0:
			temp = (power(a, n, i) + power(b, n, i)) % i
			if temp == 0:
